const group = new THREE.Group();
const corniceShape = new THREE.Shape();
corniceShape.moveTo(-width/2, -depth/2);
corniceShape.lineTo(width/2, -depth/2);
corniceShape.lineTo(width/2, depth/2);
corniceShape.lineTo(-width/2, depth/2);
corniceShape.lineTo(-width/2, -depth/2);
