const innerD = depth - 6;
const corniceHole = new THREE.Path();
corniceHole.moveTo(-innerW/2, -innerD/2);
corniceHole.lineTo(-innerW/2, innerD/2);
corniceHole.lineTo(innerW/2, innerD/2);
corniceHole.lineTo(innerW/2, -innerD/2);
corniceHole.lineTo(-innerW/2, -innerD/2);
corniceShape.holes.push(corniceHole);
const corniceGeom = new THREE.ExtrudeGeometry(corniceShape, { depth: 0.3, bevelEnabled: false });
corniceGeom.rotateX(Math.PI / 2);
corniceGeom.translate(0, height/2, 0);
group.add(new THREE.Mesh(corniceGeom));
const archShape = new THREE.Shape();
const aw = width - 0.6;
const ad = depth - 0.6;
archShape.moveTo(-aw/2, -ad/2);
archShape.lineTo(aw/2, -ad/2);
archShape.lineTo(aw/2, ad/2);
archShape.lineTo(-aw/2, ad/2);
archShape.lineTo(-aw/2, -ad/2);
const archHole = new THREE.Path();
const aiw = innerW + 0.6;
const aid = innerD + 0.6;
archHole.moveTo(-aiw/2, -aid/2);
archHole.lineTo(-aiw/2, aid/2);
archHole.lineTo(aiw/2, aid/2);
archHole.lineTo(aiw/2, -aid/2);
archHole.lineTo(-aiw/2, -aid/2);
archShape.holes.push(archHole);
const archGeom = new THREE.ExtrudeGeometry(archShape, { depth: 0.2, bevelEnabled: false });
archGeom.rotateX(Math.PI / 2);
archGeom.translate(0, height/2 - 0.3, 0);
group.add(new THREE.Mesh(archGeom));
const baseGeom = new THREE.ExtrudeGeometry(archShape, { depth: 0.5, bevelEnabled: false });
baseGeom.rotateX(Math.PI / 2);
baseGeom.translate(0, -height/2 + 0.5, 0);
group.add(new THREE.Mesh(baseGeom));
const colRadius = 0.35;
const colHeight = height - 1.0;
const colGeom = new THREE.CylinderGeometry(colRadius*0.8, colRadius, colHeight, 16);
const numColsX = 8;
const numColsZ = 8;
const colX = 7.6;
const colZ = 7.6;
for(let i=0; i<numColsX; i++) {
  const x = -colX + (colX * 2 / (numColsX-1)) * i;
  const col1 = new THREE.Mesh(colGeom);
  col1.position.set(x, 0, -colZ);
  group.add(col1);
  const col2 = new THREE.Mesh(colGeom);
  col2.position.set(x, 0, colZ);
  group.add(col2);
}
for(let i=1; i<numColsZ-1; i++) {
  const z = -colZ + (colZ * 2 / (numColsZ-1)) * i;
  const col3 = new THREE.Mesh(colGeom);
  col3.position.set(-colX, 0, z);
  group.add(col3);
  const col4 = new THREE.Mesh(colGeom);
  col4.position.set(colX, 0, z);
  group.add(col4);
}
return group;
